{
  "title": "Belém and Bairro Alto, no long rides",
  "summary": "A relaxed day split between Belém's riverside history and Bairro Alto's easygoing streets, with meals right beside the sights and no long rides.",
  "stops": [
    {
      "poi_id": "p1",
      "kind": "activity",
      "must_do_id": "m1",
      "note": "The one must-do of the day, and a proper riverside beauty. Grilled sardines can wait; history first."
    },
    {
      "poi_id": "p20",
      "kind": "meal",
      "must_do_id": null,
      "note": "A short hop from Belém, with proper vegetarian choices so nobody goes hungry between towers and trams."
    },
    {
      "poi_id": "p9",
      "kind": "activity",
      "must_do_id": null,
      "note": "A breezy viewpoint to stretch the legs and let the city do the talking. No long ride, just a little hill."
    },
    {
      "poi_id": "p13",
      "kind": "activity",
      "must_do_id": null,
      "note": "Street food, market buzz and photo corners all in one. We stay close, so the night owls can linger."
    },
    {
      "poi_id": "p16",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner right where the evening starts, vegan and welcoming. Come for the grilled sardines, stay for the grilled vegetables."
    },
    {
      "poi_id": "p11",
      "kind": "activity",
      "must_do_id": null,
      "note": "Bairro Alto after dark, a gentle festa of lights and chatter. Close to everything, so no one needs a long ride home."
    }
  ]
}
